1	package registry
2	
3	import (
4		"fmt"
5		"os"
6		"path/filepath"
7		"strings"
8	)
9	
10	// A bundle id names the directory under .okf/vendor that `okf pull` and
11	// `okf restore` write into, and that rollback and `okf vendor remove` delete
12	// recursively. Ids arrive from a registry manifest or from a repository's
13	// okf.lock, so they are untrusted input: before any of those operations touch
14	// the filesystem, the id must be a canonical relative path and its directory
15	// must resolve (through symlinks) to a location inside the vendor root.
16	
17	// ValidateBundleID accepts any canonical relative slash-separated path, such as
18	// "nextjs-15", "peter/django-5-rules", "@peter/django-5-rules" or deeper nested
19	// ids, and rejects only what could leave the vendor root: empty ids, absolute
20	// or volume-qualified paths, "", "." or ".." segments, backslashes and NUL bytes.
21	func ValidateBundleID(id string) error {
22		switch {
23		case id == "":
24			return fmt.Errorf("unsafe bundle id %q: empty id", id)
25		case strings.ContainsRune(id, 0):
26			return fmt.Errorf("unsafe bundle id %q: contains NUL byte", id)
27		case strings.ContainsRune(id, '\\'):
28			return fmt.Errorf("unsafe bundle id %q: contains backslash", id)
29		case strings.HasPrefix(id, "/") || filepath.IsAbs(filepath.FromSlash(id)) || filepath.VolumeName(filepath.FromSlash(id)) != "":
30			return fmt.Errorf("unsafe bundle id %q: absolute path", id)
31		}
32		for _, seg := range strings.Split(id, "/") {
33			switch seg {
34			case "..":
35				return fmt.Errorf("unsafe bundle id %q: parent directory traversal", id)
36			case "", ".":
37				return fmt.Errorf("unsafe bundle id %q: non-canonical path", id)
38			}
39		}
40		return nil
41	}
42	
43	// VendorRoot returns the vendor directory of a workspace.
44	func VendorRoot(workspace string) string {
45		return filepath.Join(workspace, ".okf", "vendor")
46	}
47	
48	// ResolveVendorDir validates id and returns the symlink-resolved directory it
49	// installs into. The vendor root must resolve inside the workspace, and the
50	// bundle directory strictly inside the vendor root. Neither has to exist yet.
51	func ResolveVendorDir(workspace, id string) (string, error) {
52		if err := ValidateBundleID(id); err != nil {
53			return "", err
54		}
55		root, err := resolvedVendorRoot(workspace)
56		if err != nil {
57			return "", err
58		}
59		return containedPath(root, filepath.Join(VendorRoot(workspace), filepath.FromSlash(id)), true, fmt.Sprintf("bundle id %q", id))
60	}
61	
62	// RemoveVendorDir removes an installed (or partially installed) bundle and,
63	// for nested ids, its parent directory if that is left empty. Both paths are
64	// re-resolved immediately before removal and must lie strictly inside the
65	// vendor root, so a cleanup can never delete outside it. The bundle directory
66	// itself is not followed if it is a symlink: the link is removed, as
67	// os.RemoveAll would.
68	func RemoveVendorDir(workspace, id string) error {
69		if err := ValidateBundleID(id); err != nil {
70			return err
71		}
72		root, err := resolvedVendorRoot(workspace)
73		if err != nil {
74			return err
75		}
76		kind := fmt.Sprintf("bundle id %q", id)
77		dir, err := containedPath(root, filepath.Join(VendorRoot(workspace), filepath.FromSlash(id)), false, kind)
78		if err != nil {
79			return err
80		}
81		if err := os.RemoveAll(dir); err != nil {
82			return err
83		}
84		if !strings.Contains(id, "/") {
85			return nil
86		}
87		// Best effort: the parent is only removed if it is empty and strictly
88		// inside the vendor root (never the vendor root itself).
89		if parent, err := containedPath(root, filepath.Dir(dir), false, kind); err == nil {
90			if entries, err := os.ReadDir(parent); err == nil && len(entries) == 0 {
91				_ = os.Remove(parent)
92			}
93		}
94		return nil
95	}
96	
97	// Staging is a fresh directory that one install extracts and validates a
98	// bundle in before it is moved into .okf/vendor. A failed install discards
99	// only this directory, so a rollback never deletes anything this invocation
100	// did not create (in particular not a previous installation or a directory a
101	// hostile id or symlink points at).
102	type Staging struct {
103		Dir  string
104		info os.FileInfo
105	}
106	
107	// NewStaging creates a staging directory for workspace. It lives in the
108	// resolved .okf directory (outside the vendor root, so vendor discovery never
109	// sees a half-installed bundle), or in the vendor root itself if .okf does not
110	// resolve inside the workspace.
111	func NewStaging(workspace string) (*Staging, error) {
112		if err := os.MkdirAll(VendorRoot(workspace), 0o755); err != nil {
113			return nil, fmt.Errorf("cannot create vendor root: %w", err)
114		}
115		root, err := resolvedVendorRoot(workspace)
116		if err != nil {
117			return nil, err
118		}
119		parent := root
120		ws, err := resolvePath(workspace, true)
121		if err != nil {
122			return nil, err
123		}
124		if okfDir, err := resolvePath(filepath.Join(workspace, ".okf"), true); err == nil && within(ws, okfDir) && okfDir != ws {
125			parent = okfDir
126		}
127		dir, err := os.MkdirTemp(parent, ".vendor-staging-")
128		if err != nil {
129			return nil, fmt.Errorf("cannot create staging dir: %w", err)
130		}
131		info, err := os.Lstat(dir)
132		if err != nil {
133			return nil, err
134		}
135		return &Staging{Dir: dir, info: info}, nil
136	}
137	
138	// Discard removes the staging directory, and only if it is still the
139	// directory NewStaging created (never a symlink swapped in for it).
140	func (s *Staging) Discard() error {
141		if err := s.verify(); err != nil {
142			return err
143		}
144		return os.RemoveAll(s.Dir)
145	}
146	
147	// Commit moves the staged bundle into place as the vendor directory of id.
148	// The destination is re-resolved and must lie strictly inside the vendor
149	// root. An existing installation (--force) is moved aside and removed only
150	// after the new one is in place; if it is a symlink, the link itself is
151	// replaced, never followed.
152	func (s *Staging) Commit(workspace, id string) error {
153		if err := ValidateBundleID(id); err != nil {
154			return err
155		}
156		if err := s.verify(); err != nil {
157			return err
158		}
159		root, err := resolvedVendorRoot(workspace)
160		if err != nil {
161			return err
162		}
163		kind := fmt.Sprintf("bundle id %q", id)
164		dest, err := containedPath(root, filepath.Join(VendorRoot(workspace), filepath.FromSlash(id)), false, kind)
165		if err != nil {
166			return err
167		}
168		if err := os.MkdirAll(filepath.Dir(dest), 0o755); err != nil {
169			return fmt.Errorf("cannot create vendor dir: %w", err)
170		}
171		if _, err := containedPath(root, dest, false, kind); err != nil {
172			return err
173		}
174		if _, err := os.Lstat(dest); os.IsNotExist(err) {
175			return os.Rename(s.Dir, dest)
176		}
177		aside, err := os.MkdirTemp(filepath.Dir(s.Dir), ".vendor-replaced-")
178		if err != nil {
179			return fmt.Errorf("cannot create staging dir: %w", err)
180		}
181		old := filepath.Join(aside, "previous")
182		if err := os.Rename(dest, old); err != nil {
183			_ = os.Remove(aside)
184			return fmt.Errorf("cannot replace existing installation: %w", err)
185		}
186		if err := os.Rename(s.Dir, dest); err != nil {
187			_ = os.Rename(old, dest)
188			_ = os.Remove(aside)
189			return fmt.Errorf("cannot move staged bundle into place: %w", err)
190		}
191		return os.RemoveAll(aside)
192	}
193	
194	func (s *Staging) verify() error {
195		info, err := os.Lstat(s.Dir)
196		if err != nil {
197			return err
198		}
199		if !info.IsDir() || !os.SameFile(info, s.info) {
200			return fmt.Errorf("refusing staging dir %q: no longer the directory this install created", s.Dir)
201		}
202		return nil
203	}
204	
205	// resolvedVendorRoot resolves the workspace and its .okf/vendor root through
206	// symlinks and refuses a vendor root that lies outside the workspace (for
207	// example a repository that ships `.okf -> /elsewhere`).
208	func resolvedVendorRoot(workspace string) (string, error) {
209		ws, err := resolvePath(workspace, true)
210		if err != nil {
211			return "", fmt.Errorf("failed to resolve workspace %q: %w", workspace, err)
212		}
213		root, err := resolvePath(VendorRoot(workspace), true)
214		if err != nil {
215			return "", fmt.Errorf("failed to resolve vendor root: %w", err)
216		}
217		if !within(ws, root) {
218			return "", fmt.Errorf("refusing vendor root %q: resolves to %q outside workspace %q", VendorRoot(workspace), root, ws)
219		}
220		return root, nil
221	}
222	
223	// containedPath resolves target (see resolvePath) and returns it only if it
224	// lies strictly inside the already-resolved root.
225	func containedPath(root, target string, followLeaf bool, kind string) (string, error) {
226		resolved, err := resolvePath(target, followLeaf)
227		if err != nil {
228			return "", fmt.Errorf("failed to resolve %s path %q: %w", kind, target, err)
229		}
230		if !within(root, resolved) || resolved == root {
231			return "", fmt.Errorf("refusing %s: %q resolves to %q outside %q", kind, target, resolved, root)
232		}
233		return resolved, nil
234	}
235	
236	// resolvePath returns the absolute path of target with symlinks resolved in its
237	// closest existing ancestor, so paths not yet created resolve too. With
238	// followLeaf false the final element is not resolved, so a symlink at target
239	// is treated as the link itself.
240	func resolvePath(target string, followLeaf bool) (string, error) {
241		abs, err := filepath.Abs(target)
242		if err != nil {
243			return "", err
244		}
245		existing, missing, leaf := abs, "", ""
246		if !followLeaf {
247			existing, leaf = filepath.Dir(abs), filepath.Base(abs)
248		}
249		for {
250			if _, err := os.Lstat(existing); err == nil {
251				break
252			}
253			parent := filepath.Dir(existing)
254			if parent == existing {
255				break
256			}
257			missing = filepath.Join(filepath.Base(existing), missing)
258			existing = parent
259		}
260		resolved, err := filepath.EvalSymlinks(existing)
261		if err != nil {
262			return "", err
263		}
264		return filepath.Join(resolved, missing, leaf), nil
265	}
266	
267	// within reports whether path equals root or lies below it (filepath.Rel, not a
268	// string prefix).
269	func within(root, path string) bool {
270		rel, err := filepath.Rel(root, path)
271		return err == nil && rel != ".." && !strings.HasPrefix(rel, ".."+string(filepath.Separator)) && !filepath.IsAbs(rel)
272	}
