		got, err := registry.ResolveVendorDir(ws, "alias/rules")
		if err != nil || got != filepath.Join(ws, ".okf", "vendor", "real", "rules") {
			t.Fatalf("got %q, %v", got, err)
		}
	})
	t.Run("unsafe id", func(t *testing.T) {
		ws, _ := vendorWorkspace(t)
