			t.Fatalf("expected unsafe id refusal, got %v", err)
		}
	})
	t.Run("symlink in vendor root escapes", func(t *testing.T) {
		ws, outside := vendorWorkspace(t)
		mustSymlink(t, outside, filepath.Join(ws, ".okf", "vendor", "evil"))
